def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    f = [i - 1 for i in range(n + 1)]
    for c in range(n):
        for l, r in ((c, c), (c, c + 1)):
            while l >= 0 and r < n and s[l] == s[r]:
                if f[l] + 1 < f[r + 1]:
                    f[r + 1] = f[l] + 1
                l -= 1
                r += 1
    print(f[n])


