import sys
from functools import lru_cache

s = sys.stdin.read().split()[0]
n = len(s)


@lru_cache(maxsize=None)
def best(i):
    if i == n:
        return -1
    res = n
    for j in range(i + 1, n + 1):
        t = s[i:j]
        if t == t[::-1]:
            res = min(res, 1 + best(j))
    return res


print(best(0))

